package main

import (
    "log"
    "net/http"
    "sync"
    "github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
    CheckOrigin: func(r *http.Request) bool { return true },
}

type ConnectionManager struct {
    connections map[*websocket.Conn]bool
    mu          sync.Mutex
}

func (cm *ConnectionManager) addConnection(conn *websocket.Conn) {
    cm.mu.Lock()
    defer cm.mu.Unlock()
    cm.connections[conn] = true
}

func (cm *ConnectionManager) removeConnection(conn *websocket.Conn) {
    cm.mu.Lock()
    defer cm.mu.Unlock()
    delete(cm.connections, conn)
    conn.Close() // 未检查错误
}

func (cm *ConnectionManager) broadcast(message []byte) {
    cm.mu.Lock()
    defer cm.mu.Unlock()
    for conn := range cm.connections {
        go func(c *websocket.Conn) {
            err := c.WriteMessage(websocket.TextMessage, message)
            if err != nil {
                log.Println("Broadcast error:", err)
                cm.removeConnection(c) // 可能死锁
            }
        }(conn)
    }
}

func handleWebSocket(cm *ConnectionManager, w http.ResponseWriter, r *http.Request) {
    conn, err := upgrader.Upgrade(w, r, nil)
    if err != nil {
        log.Println("Upgrade failed:", err)
        return
    }
    cm.addConnection(conn)

    go func() {
        defer cm.removeConnection(conn)
        for {
            _, message, err := conn.ReadMessage()
            if err != nil {
                log.Println("Read error:", err)
                break
            }
            log.Printf("Received: %s", message)
            cm.broadcast(message)
        }
    }()
}

func main() {
    cm := &ConnectionManager{connections: make(map[*websocket.Conn]bool)}
    http.HandleFunc("/ws", func(w http.ResponseWriter, r *http.Request) {
        handleWebSocket(cm, w, r)
    })
    log.Fatal(http.ListenAndServe(":8080", nil))
}

