package main

import (
    "fmt"
    "strings"
    "time"
)

func analyzeLogs(logs []string) map[string]int {
    result := make(map[string]int)
    for _, log := range logs {
        parts := strings.Split(log, " ")
        if len(parts) < 3 {
            continue
        }
        ip := parts[0]
        status := parts[2]
        result[ip]++
        result[status]++
    }
    return result
}

