import time
from typing import Optional, Dict, Any

class APIClient:
    def __init__(self, base_url: str, timeout: int = 10, max_retries: int = 3):
        self.base_url = base_url
        self.timeout = timeout
        self.max_retries = max_retries
        self.session = None

    def _ensure_session(self):
        if self.session is None:
            self.session = requests.Session()

    def get_user_data(self, user_id: int) -> Optional[Dict[str, Any]]:
        self._ensure_session()
        url = f"{self.base_url}/users/{user_id}"
        for attempt in range(self.max_retries):
            try:
                response = self.session.get(url, timeout=self.timeout)
                response.raise_for_status()
                return response.json()
            except requests.exceptions.Timeout:
                if attempt < self.max_retries - 1:
                    time.sleep(1)
                    continue
                else:
                    print("Request timed out after retries")
                    return None
            except requests.exceptions.RequestException as e:
                print(f"Error: {e}")
                return None
        return None

    def post_data(self, endpoint: str, data: Dict[str, Any]) -> bool:
        url = f"{self.base_url}/{endpoint}"
        with requests.Session() as session:
            try:
                response = session.post(url, json=data, timeout=self.timeout)
                response.raise_for_status()
                return True
            except requests.exceptions.RequestException as e:
                print(f"Error: {e}")
                return False

