    private PaymentStrategy strategy;
    private List<Double> amounts;

    public PaymentProcessor(PaymentStrategy strategy, List<Double> amounts) {
        this.strategy = strategy;
        this.amounts = amounts;
    }

    public void processPayments() {
        for (Double amount : amounts) {
            try {
                strategy.pay(amount);
                System.out.println("Payment successful for amount: " + amount);
            } catch (Exception e) {
                System.out.println("Error processing payment: " + e.getMessage());
            }
        }
    }
}

interface PaymentStrategy {
    void pay(double amount) throws PaymentException;
}

class CreditCardPayment implements PaymentStrategy {
    private String cardNumber;

    public CreditCardPayment(String cardNumber) {
        this.cardNumber = cardNumber;
    }

    @Override
    public void pay(double amount) throws PaymentException {
        if (amount <= 0) {
            throw new PaymentException("Amount must be positive");
        }
        if (cardNumber == null || cardNumber.isEmpty()) {
            throw new PaymentException("Invalid card number");
        }
        // Simulate payment logic
        System.out.println("Processing credit card payment of " + amount + " with card " + cardNumber);
    }
}

class PaymentException extends Exception {
    public PaymentException(String message) {
        super(message);
    }
}

