CREATE OR REPLACE PROCEDURE update_pdf_generation_failure(
    p_task_id UUID,
    p_error_code VARCHAR(50),
    p_error_message TEXT
) LANGUAGE plpgsql
AS $$
DECLARE
    v_current_status VARCHAR(20);
    v_retry_count INT;
    v_max_retries INT DEFAULT 3;
    v_log_id UUID;
    v_system_timestamp TIMESTAMP := NOW();
BEGIN
    -- 启动事务
    BEGIN
        -- 获取当前任务状态和重试次数
        SELECT status, retry_count, max_retries
        INTO v_current_status, v_retry_count, v_max_retries
        FROM pdf_generation_tasks
        WHERE task_id = p_task_id
        FOR UPDATE; -- 加锁防止并发更新

        -- 检查任务状态
        IF v_current_status = 'COMPLETED' THEN
            RAISE EXCEPTION 'Cannot update a completed task.';
        END IF;

        -- 更新任务状态
        IF v_retry_count < v_max_retries THEN
            -- 重试次数未超限，更新为FAILED_RETRYABLE
            UPDATE pdf_generation_tasks
            SET 
                status = 'FAILED_RETRYABLE',
                retry_count = retry_count + 1,
                last_error_code = p_error_code,
                last_error_message = LEFT(p_error_message, 1000), -- 截断过长的错误信息
                updated_at = v_system_timestamp
            WHERE task_id = p_task_id;
        ELSE
            -- 重试次数已超限，更新为FAILED_FINAL
            UPDATE pdf_generation_tasks
            SET 
                status = 'FAILED_FINAL',
                retry_count = retry_count + 1,
                last_error_code = p_error_code,
                last_error_message = LEFT(p_error_message, 1000),
                updated_at = v_system_timestamp
            WHERE task_id = p_task_id;
        END IF;

        -- 生成并插入错误日志
        v_log_id := gen_random_uuid();
        INSERT INTO pdf_generation_logs (
            log_id, task_id, log_type, error_code, error_message, created_at
        ) VALUES (
            v_log_id, p_task_id, 'ERROR', p_error_code, p_error_message, v_system_timestamp
        );

        -- 如果日志插入成功，提交内部事务块？
        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            -- 发生任何错误，回滚所有操作
            ROLLBACK;
            -- 重新抛出异常给外部调用者
            RAISE;
    END;

    -- 记录操作完成（外部事务块）
    INSERT INTO system_audit_log (operation, entity_id, performed_at)
    VALUES ('PDF_TASK_FAILURE_UPDATE', p_task_id, v_system_timestamp);

EXCEPTION
    WHEN OTHERS THEN
        -- 捕获存储过程顶层异常
        -- 理论上，由于内部有事务块，这里不应到达
        RAISE NOTICE 'Unexpected error at top level: %', SQLERRM;
END;
$$;

