import json
import os
from datetime import datetime

class CacheReader:
    def __init__(self, cache_dir='cache'):
        self.cache_dir = cache_dir
        if not os.path.exists(self.cache_dir):
            os.makedirs(self.cache_dir)

    def read_cache(self, key):
        cache_file = os.path.join(self.cache_dir, f'{key}.json')
        if os.path.exists(cache_file):
            try:
                with open(cache_file, 'r') as f:
                    data = json.load(f)
                    if 'expiry' in data and data['expiry'] < datetime.now().timestamp():
                        os.remove(cache_file)
                        return None
                    return data.get('value')
            except Exception as e:
                print(f"Error reading cache for key {key}: {e}")
                return None
        else:
            return None

    def write_cache(self, key, value, ttl_seconds=3600):
        cache_file = os.path.join(self.cache_dir, f'{key}.json')
        try:
            expiry = datetime.now().timestamp() + ttl_seconds
            data = {'value': value, 'expiry': expiry}
            with open(cache_file, 'w') as f:
                json.dump(data, f)
        except Exception as e:
            print(f"Error writing cache for key {key}: {e}")

